source.patch:
From 15bbf6f3377e6446e88300b9c5383179091fe270 Mon Sep 17 00:00:00 2001
From: Nikita Popov <nikita.ppv@gmail.com>
Date: Fri, 24 Sep 2021 13:11:11 +0200
Subject: [PATCH] Automatically determine whether to reuse get_iterator()

Same as with the IteratorAggregate case, allow reusing get_iterator
if none of the Iterator methods are overridden. Drop the
REUSE_GET_ITERATOR flag that previously allowed ArrayIterator to
opt-in to unconditional get_iterator reuse, and drop the override
handling it did, in favor of the automated approach.
---
 Zend/tests/foreach_004.phpt                   | 65 -----------------
 Zend/zend_compile.h                           |  5 +-
 Zend/zend_interfaces.c                        | 17 +++--
 ext/spl/spl_array.c                           | 72 +++----------------
 ext/spl/tests/bug54281.phpt                   |  5 +-
 ...iveIteratorIterator_endchildren_error.phpt |  5 +-
 6 files changed, 24 insertions(+), 145 deletions(-)
 delete mode 100644 Zend/tests/foreach_004.phpt

diff --git a/Zend/tests/foreach_004.phpt b/Zend/tests/foreach_004.phpt
deleted file mode 100644
index afb98a9..0000000
--- a/Zend/tests/foreach_004.phpt
+++ /dev/null
@@ -1,65 +0,0 @@
---TEST--
-Iterator exceptions in foreach by reference
---FILE--
-<?php
-class IT extends ArrayIterator {
-    private $n = 0;
-
-    function __construct($trap = null) {
-        parent::__construct([0, 1]);
-        $this->trap = $trap;
-    }
-
-    function trap($trap) {
-        if ($trap === $this->trap) {
-            throw new Exception($trap);
-        }
-    }
-
-    function rewind(): void  {$this->trap(__FUNCTION__); parent::rewind();}
-    function valid(): bool   {$this->trap(__FUNCTION__); return parent::valid();}
-    function key(): string|int|null { $this->trap(__FUNCTION__); return parent::key(); }
-    function next(): void    {$this->trap(__FUNCTION__); parent::next();}
-}
-
-foreach(['rewind', 'valid', 'key', 'next'] as $trap) {
-    $obj = new IT($trap);
-    try {
-        // IS_CV
-        foreach ($obj as $key => &$val) echo "$val\n";
-    } catch (Exception $e) {
-        echo $e->getMessage() . "\n";
-    }
-    unset($obj);
-
-    try {
-        // IS_VAR
-        foreach (new IT($trap) as $key => &$val) echo "$val\n";
-    } catch (Exception $e) {
-        echo $e->getMessage() . "\n";
-    }
-
-    try {
-        // IS_TMP_VAR
-        foreach ((object)new IT($trap) as $key => &$val) echo "$val\n";
-    } catch (Exception $e) {
-        echo $e->getMessage() . "\n";
-    }
-}
-?>
---EXPECT--
-rewind
-rewind
-rewind
-valid
-valid
-valid
-key
-key
-key
-0
-next
-0
-next
-0
-next
